/// Prefixo dos caminhos da variante regular.
pub const REGULAR_PREFIX: &str = "iconoir/regular/";
/// Prefixo dos caminhos da variante solid.
pub const SOLID_PREFIX: &str = "iconoir/solid/";

/// Resolve um caminho `iconoir/<variante>/<nome>.svg` nos bytes do SVG. `None` se não existir.
///
/// Busca binária (as tabelas são ordenadas por caminho) — com 1671 entradas, a varredura linear
/// custaria caro: o `gpui::svg()` resolve o asset a cada paint, e uma galeria com centenas de
/// ícones na tela faria dezenas de milhares de comparações por frame.
pub fn lookup(path: &str) -> Option<&'static [u8]> {
    let table = if path.starts_with(SOLID_PREFIX) {
        SOLID
    } else if path.starts_with(REGULAR_PREFIX) {
        REGULAR
    } else {
        return None;
    };
    table
        .binary_search_by(|(p, _)| (*p).cmp(path))
        .ok()
        .map(|i| table[i].1)
}

/// `true` se o caminho existe. Use antes de renderizar um nome vindo de dados — um caminho
/// errado não gera erro no GPUI, o ícone só não aparece.
pub fn has(path: &str) -> bool {
    lookup(path).is_some()
}

/// Extrai `<nome>` de `iconoir/<variante>/<nome>.svg`. Os caminhos vêm das tabelas (consts, logo
/// `&'static str`), e um slice de `&'static str` continua `'static` — sem cópia nem `unsafe`.
fn name_of(path: &'static str, prefix: &str) -> &'static str {
    path.strip_prefix(prefix)
        .and_then(|s| s.strip_suffix(".svg"))
        .unwrap_or(path)
}

/// Nomes dos ícones **regular** (sem prefixo nem `.svg`), em ordem.
pub fn regular_names() -> impl Iterator<Item = &'static str> {
    REGULAR.iter().map(|(p, _)| name_of(p, REGULAR_PREFIX))
}

/// Nomes dos ícones **solid** (sem prefixo nem `.svg`), em ordem.
pub fn solid_names() -> impl Iterator<Item = &'static str> {
    SOLID.iter().map(|(p, _)| name_of(p, SOLID_PREFIX))
}

/// Total de ícones embutidos (as duas variantes somadas).
pub fn count() -> usize {
    REGULAR.len() + SOLID.len()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::collections::BTreeSet;

    /// **A garantia de completude.** Compara as tabelas com o que está no disco: se um SVG foi
    /// vendorizado mas não entrou na tabela (regeneração parcial, arquivo novo num upgrade do
    /// Iconoir), ele sumiria da UI sem nenhum sinal. Aqui vira falha de teste.
    #[test]
    fn nenhum_arquivo_do_disco_ficou_de_fora() {
        for (variante, prefixo, tabela) in [
            ("regular", REGULAR_PREFIX, REGULAR),
            ("solid", SOLID_PREFIX, SOLID),
        ] {
            let dir = format!("{}/assets/iconoir/{variante}", env!("CARGO_MANIFEST_DIR"));
            let no_disco: BTreeSet<String> = std::fs::read_dir(&dir)
                .unwrap_or_else(|e| panic!("não consegui ler {dir}: {e}"))
                .map(|e| e.expect("entrada de diretório").file_name())
                .map(|n| n.to_string_lossy().into_owned())
                .filter(|n| n.ends_with(".svg"))
                .collect();
            let na_tabela: BTreeSet<String> = tabela
                .iter()
                .map(|(p, _)| p.strip_prefix(prefixo).expect("prefixo").to_string())
                .collect();

            let faltando: Vec<_> = no_disco.difference(&na_tabela).collect();
            let sobrando: Vec<_> = na_tabela.difference(&no_disco).collect();
            assert!(
                faltando.is_empty(),
                "{variante}: {} SVG(s) no disco fora da tabela: {faltando:?}",
                faltando.len()
            );
            assert!(
                sobrando.is_empty(),
                "{variante}: {} entrada(s) na tabela sem arquivo: {sobrando:?}",
                sobrando.len()
            );
        }
    }

    /// A busca binária da [`lookup`] só está correta se as tabelas estiverem ordenadas por
    /// caminho. Uma tabela fora de ordem faz ícones "não existirem" de forma intermitente —
    /// o pior tipo de bug pra diagnosticar visualmente.
    #[test]
    fn tabelas_ordenadas_por_caminho() {
        for (nome, tabela) in [("REGULAR", REGULAR), ("SOLID", SOLID)] {
            let paths: Vec<&str> = tabela.iter().map(|(p, _)| *p).collect();
            let mut ordenado = paths.clone();
            ordenado.sort_unstable();
            assert_eq!(paths, ordenado, "tabela {nome} fora de ordem");
        }
    }

    /// Nenhuma entrada duplicada (a busca binária devolveria uma delas arbitrariamente).
    #[test]
    fn nenhum_caminho_duplicado() {
        let mut todos: Vec<&str> = REGULAR.iter().chain(SOLID).map(|(p, _)| *p).collect();
        let total = todos.len();
        todos.sort_unstable();
        todos.dedup();
        assert_eq!(total, todos.len(), "há caminhos duplicados entre REGULAR/SOLID");
    }

    /// Todo ícone resolve pra bytes não-vazios e parece um SVG. Pega `include_bytes!` de arquivo
    /// truncado/vazio — que renderizaria um ícone em branco, sem erro.
    #[test]
    fn toda_entrada_resolve_svg_nao_vazio() {
        for (path, _) in REGULAR.iter().chain(SOLID) {
            let bytes = lookup(path).unwrap_or_else(|| panic!("lookup falhou para {path}"));
            assert!(!bytes.is_empty(), "SVG vazio: {path}");
            let head = std::str::from_utf8(&bytes[..bytes.len().min(64)]).unwrap_or("");
            assert!(head.contains("<svg"), "não parece um SVG: {path}");
        }
    }

    /// `lookup` casa cada variante com a SUA tabela — um nome que existe nas duas não pode
    /// devolver os bytes da outra (regular e solid desenham coisas diferentes).
    #[test]
    fn lookup_nao_confunde_as_variantes() {
        // `heart` existe nas duas variantes.
        let r = lookup("iconoir/regular/heart.svg").expect("regular/heart");
        let s = lookup("iconoir/solid/heart.svg").expect("solid/heart");
        assert_ne!(r, s, "regular e solid devolveram os mesmos bytes");
        assert!(std::str::from_utf8(r).unwrap().contains("stroke="));
        assert!(std::str::from_utf8(s).unwrap().contains("fill=\"currentColor\""));
    }

    /// Caminho fora do namespace, variante inexistente e nome inexistente devolvem `None`
    /// (não podem cair na tabela errada nem entrar em pânico).
    #[test]
    fn caminhos_invalidos_sao_none() {
        assert!(lookup("iconoir/regular/nao-existe.svg").is_none());
        assert!(lookup("iconoir/duotone/heart.svg").is_none());
        assert!(lookup("icons/check.svg").is_none()); // ícone nativo, não é do iconoir
        assert!(lookup("").is_none());
        assert!(!has("iconoir/regular/nao-existe.svg"));
    }

    /// Os nomes saem sem prefixo nem extensão (é o que a busca do storybook exibe e filtra).
    #[test]
    fn nomes_vem_limpos() {
        let nomes: Vec<&str> = regular_names().collect();
        assert_eq!(nomes.len(), REGULAR.len());
        assert!(nomes.contains(&"heart"));
        assert!(nomes.iter().all(|n| !n.contains('/') && !n.ends_with(".svg")));
        assert!(solid_names().any(|n| n == "heart"));
    }
}
